import React, { useEffect, useState } from 'react';
import { Keyboard, Platform, useWindowDimensions } from 'react-native';
import { type FormStore, useFormStore } from './features/formStore';
import { useFieldScroll } from './validate';

/**
 * The KeyboardAvoidingView behaviour for this screen: 'padding' while a
 * keyboard is up, none once it is gone. Android reports a closed keyboard's top
 * edge above the system bars on an edge-to-edge window, and the view kept that
 * gap as padding after every keyboard; dropping the behaviour clears it.
 */
export function useKeyboardBehavior(): 'padding' | undefined {
  const [shown, setShown] = useState(false);
  useEffect(() => {
    if (Platform.OS === 'ios') return undefined;
    const up = Keyboard.addListener('keyboardDidShow', () => setShown(true));
    const down = Keyboard.addListener('keyboardDidHide', () => setShown(false));
    return () => {
      up.remove();
      down.remove();
    };
  }, []);
  return Platform.OS === 'ios' || shown ? 'padding' : undefined;
}

/**
 * Subscribe to viewport changes so BOTH halves of a screen's scaling agree.
 *
 * A screen's lengths arrive two ways: as `vw` inside a className, which
 * NativeWind recomputes from Dimensions whenever the viewport changes, and as
 * s()/sv() inside a style object, which is a plain function evaluated once per
 * render. With nothing subscribed, a resize or rotation moved the classed half
 * and left the inline half at its old values — the layout came apart, which a
 * browser window drag makes obvious. (Before the classes existed both halves
 * were equally stale, so it stayed coherent while not adapting.)
 *
 * The value is deliberately dropped: the hook's job is to re-render, after
 * which s()/sv() read the new Dimensions and the two halves match again.
 */
export function useViewport(): void {
  useWindowDimensions();
}

