function newRowId(): string {
  rowSeq += 1;
  return 'r' + Date.now().toString(36) + rowSeq.toString(36);
}

/** Append a row, honouring the design's `[repeat max=n]` cap when it set one. */
export function addRow(
  values: FormStore['values'],
  setField: (k: string, v: any) => void,
  key: string,
  max?: number,
): void {
  const rows = rowsOf(values, key);
  if (max !== undefined && rows.length >= max) return;
  setField(key, [...rows, { id: newRowId() }]);
}

/** Remove a row BY ID — never the last one, or the section would vanish. */
export function removeRow(
  values: FormStore['values'],
  setField: (k: string, v: any) => void,
  key: string,
  rid: string,
): void {
  const rows = rowsOf(values, key);
  if (rows.length > 1)
    setField(
      key,
      rows.filter((r) => ridOf(r) !== rid),
    );
}
